				if var6 ~= v2.Group then
					arg1:Reply((([[
%*
%*]]):format(v2.Group, (string.rep("-", #v2.Group)))))

				end

				arg1:Reply(if v2.Description then ("%* - %*"):format(v2.Name, v2.Description) else v2.Name)
