	for k1, v1 in pairs(arg1) do
		local var1 = arg2[k1]
		local var2 = math.floor(var1 / #v1 * 100) / 100
		local var3 = math.floor((var1 - var2 * (#v1 - 1)) * 100) / 100
		for k2, v2 in ipairs(v1) do
