		return var5, tbl1.Seasons[var5]
	end

	local var6 = (tbl1.CurrentSeason + math.floor((var3 - tbl1.RotationStartTime) / tbl1.SeasonDuration)) % #tbl1.Seasons + 1
	return var6, tbl1.Seasons[var6]
end

tbl1.GetTimeUntilNextSeason = function(arg1)
