local function _ValidateBrainrotModels()
	local var2 = var1:WaitForChild("BrainrotModels")
	local tbl2 = {}
	local tbl3 = {}
	for k1 in tbl1.CONFIG, nil do
		for k2 in var3, nil do
			local var4 = if k2 == "NORMAL" then k1 else string.lower((("%*_%*"):format(k2, k1)))
			tbl2[var4] = true
			if var2:FindFirstChild(var4) then
				continue
			end

			table.insert(tbl3, (("%* (%*, %*)"):format(var4, k1, k2)))
		end
	end

	local tbl4 = {}
	for k3, v1 in var2:GetChildren() do
		if tbl2[v1.Name] then
			continue
		end

		table.insert(tbl4, v1.Name)
	end

	if #tbl3 ~= 0 then
		table.sort(tbl3)
		warn((([=[[BrainrotsConfig] Brainrots in BrainrotsConfig with no model in BrainrotModels (%*):
  - %*]=]):format(#tbl3, (table.concat(tbl3, [[
  - ]])))))

	end

	if #tbl4 == 0 then
		return
	end

	table.sort(tbl4)
	warn((([=[[BrainrotsConfig] Models in BrainrotModels with no matching brainrot/mutation in BrainrotsConfig (%*):
  - %*]=]):format(#tbl4, (table.concat(tbl4, [[
  - ]])))))
end

if var2:IsStudio() then
	_ValidateBrainrotModels()
end

return tbl1

